import json
from ute_ue.exceptions import UeProcedureError
from ta_ue_plugin_rtg.rpc.err_jsonrpc import ErrJsonRpcError
from ta_ue_plugin_rtg.rpc.err_transport import ErrRemoteEndpointDisconnected


class RpcCall():
    """Object responsible for calling json-rpc method with error handling and logging"""
    def __init__(self, rpc_socket, logger):
        """Initialization"""
        self.rpc_socket = rpc_socket
        self.logger = logger

    def call(self, method, params, log_msg='Procedure'):
        """Wraped JsonRpcClient call method with exception handling and logging"""
        try:
            self.logger.info('{} started'.format(log_msg))
            response = self.rpc_socket.call(method, params)
        except ErrJsonRpcError as err:
            server_resp = json.loads(json.dumps(err.err))
            if 'resp' in server_resp:
                server_resp = server_resp['resp']['error']
            err_message = server_resp['message']
            # err_code = server_resp['code']
            self.logger.error('{} failed. {}'.format(log_msg, err_message))
            raise UeProcedureError(err_message)
        except ErrRemoteEndpointDisconnected:
            self.logger.error("JSON_RPC server has crashed while processing the request. "
                              "Please check uex_logs for details")
            raise
        else:
            self.logger.info('{} succeeded'.format(log_msg))
            return response
